package com.enterprise.mm.erp.warehouse.outbound;

import static org.assertj.core.api.Assertions.*;
import com.enterprise.mm.common.*;
import com.enterprise.mm.erp.warehouse.WarehouseMirrorSettings;
import com.enterprise.mm.error.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.core.io.ClassPathResource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.jdbc.datasource.init.ResourceDatabasePopulator;
import org.springframework.transaction.support.TransactionTemplate;

/** Uses the real V89 source table contracts, copied into disposable schemas without business data. */
@EnabledIfEnvironmentVariable(named="MM_WAREHOUSE_PG_URL",matches=".+")
class WarehouseOutboundPostgresTest {
    final ObjectMapper mapper=new ObjectMapper();final UUID company=UUID.randomUUID(),material=UUID.randomUUID(),warehouse=UUID.randomUUID(),contra=UUID.randomUUID();
    final String schema="wh_out_"+UUID.randomUUID().toString().replace("-","");JdbcTemplate admin,jdbc;WarehouseOutboundService service;TransactionTemplate tx;
    @BeforeEach void setup(){String url=System.getenv("MM_WAREHOUSE_PG_URL"),user=System.getenv().getOrDefault("MM_WAREHOUSE_PG_USER","mm_local"),password=System.getenv().getOrDefault("MM_WAREHOUSE_PG_PASSWORD","");admin=new JdbcTemplate(new DriverManagerDataSource(url,user,password));admin.execute("create schema "+schema);var ds=new DriverManagerDataSource(url+"?currentSchema="+schema,user,password);jdbc=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));
        for(String table:List.of("stock_movements","stock_movement_allocations","stock_movement_allocation_cost_layers","stock_balances","warehouse_posting_batches","warehouse_posting_effects","warehouse_holdings","transfer_transit_entries","transfer_shipment_allocations","stock_cost_movements","erp_exchange_envelope"))jdbc.execute("create table "+table+" (like public."+table+" including all)");
        new ResourceDatabasePopulator(new ClassPathResource("db/migration/V96__warehouse_outbound_facts.sql")).execute(ds);TenantContext.setTenant("out-test");CompanyContext.setCompany(company);service=proxy();}
    WarehouseOutboundService proxy(){var target=new WarehouseOutboundService(jdbc,mapper,new WarehouseOutboundSettings(true,new WarehouseMirrorSettings(true,"source","org"),contra.toString()));var f=new org.springframework.aop.framework.ProxyFactory(target);f.setProxyTargetClass(true);f.addAdvice(new org.springframework.transaction.interceptor.TransactionInterceptor(new DataSourceTransactionManager(jdbc.getDataSource()),new org.springframework.transaction.annotation.AnnotationTransactionAttributeSource()));return (WarehouseOutboundService)f.getProxy();}
    @AfterEach void cleanup(){if(admin!=null)admin.execute("drop schema "+schema+" cascade");TenantContext.clear();CompanyContext.clear();}
    UUID movement(String type,String reference){UUID id=UUID.randomUUID();jdbc.update("insert into stock_movements(id,tenant_id,company_id,created_at,version,is_delete,name,code,status,material_id,warehouse_id,movement_type,quantity,unit_cost,total_cost,movement_date,posted_at,reference_type) values(?,?,?,current_timestamp,0,false,'Test','OUTTEST','POSTED',?,?,?,?,10,20,'2025-04-20',current_timestamp,?)",id,"out-test",company,material,warehouse,type,new BigDecimal("2"),reference);return id;}
    void allocation(UUID id){jdbc.update("insert into stock_movement_allocations(id,tenant_id,company_id,created_at,movement_id,allocation_sequence,allocation_role,material_id,source_warehouse_id_snapshot,on_hand_delta,available_delta,reserved_delta,quarantine_delta,total_value_delta,batch_quantity_delta,currency_code_snapshot) values(?,?,?,current_timestamp,?,1,'SOURCE',?,?,-2,-2,0,0,-20,-2,'UZS')",UUID.randomUUID(),"out-test",company,id,material,warehouse);}
    Map<String,Object> capture(UUID id){return tx.execute(s->service.captureStockMovement(id));}
    @Test void immutableFactsDeduplicateRollbackAndLeaseAcknowledgementsAreFenced() throws Exception {
        UUID id=movement("WRITE_OFF",null);allocation(id);var first=capture(id);UUID operation=(UUID)first.get("operationId");assertThat(capture(id).get("replayed")).isEqualTo(true);assertThat(service.list(10,0)).hasSize(1);
        assertThatThrownBy(()->tx.execute(s->{UUID second=movement("ISSUE",null);allocation(second);service.captureStockMovement(second);throw new IllegalStateException("rollback");})).isInstanceOf(IllegalStateException.class);assertThat(service.list(10,0)).hasSize(1);
        var poll=request();JsonNode leased=mapper.valueToTree(service.poll(poll)).path("operations").get(0);assertThat(leased.path("operationId").asText()).isEqualTo(operation.toString());assertThat(mapper.valueToTree(service.poll(poll)).path("operations")).isEmpty();
        String json=leased.path("payloadJson").asText();assertThat(java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(json.getBytes(java.nio.charset.StandardCharsets.UTF_8)))).isEqualTo(leased.path("payloadHash").asText());assertThat(mapper.readTree(json).path("facts").get(0).path("quantity").asText()).isEqualTo("-2");
        var ack=request().put("revision",leased.path("revision").asLong()).put("leaseToken",leased.path("leaseToken").asText()).put("payloadHash",leased.path("payloadHash").asText()).put("status","REVIEW_REQUIRED").put("message","mapping required");assertThat(service.result(operation,ack).get("replayed")).isEqualTo(false);assertThat(service.result(operation,ack).get("replayed")).isEqualTo(true);assertThatThrownBy(()->service.result(operation,ack.deepCopy().put("status","APPLIED"))).isInstanceOf(ConflictException.class);
        CompanyContext.setCompany(UUID.randomUUID());assertThat(service.list(10,0)).isEmpty();assertThatThrownBy(()->service.detail(operation)).isInstanceOf(NotFoundException.class);
    }
    ObjectNode request(){return mapper.createObjectNode().put("protocolVersion",2).put("sourceInstanceId","source").put("organizationId","org").put("workerId","worker").put("limit",1);}
    @Test void legacyAndHoldingAreObservedWithoutAnotherStockExpense() throws Exception {
        UUID id=movement("RECEIPT",null);allocation(id);var capture=capture(id);jdbc.update("insert into erp_exchange_envelope(id,tenant_id,company_id,document_kind,document_id,document_version,payload,delivery_state,operation,posting_date) values(?,?,?,'RECEIPT',?,1,'{}','PENDING','RECEIPT','2025-04-20')",UUID.randomUUID(),"out-test",company,id);
        JsonNode polled=mapper.valueToTree(service.poll(request())).path("operations").get(0);assertThat(mapper.readTree(polled.path("payloadJson").asText()).path("policy").asText()).isEqualTo("LEGACY_LINKED");
        UUID holding=UUID.randomUUID();jdbc.update("insert into warehouse_holdings(id,tenant_id,company_id,material_id,name,active_quantity,consumed_quantity) values(?,?,?,?,'Holding',2,1)",holding,"out-test",company,material);tx.execute(s->service.captureHolding(holding));jdbc.update("update warehouse_holdings set active_quantity=1,consumed_quantity=2 where id=?",holding);tx.execute(s->service.captureHolding(holding));JsonNode detail=mapper.valueToTree(service.list(10,0)).findValue("sourceKey");assertThat(detail).isNotNull();var holdingHead=service.list(10,0).stream().filter(m->"HOLDING".equals(m.get("sourceEngine"))).findFirst().orElseThrow();assertThat(holdingHead.get("revision")).isEqualTo(2L);JsonNode versions=mapper.valueToTree(service.detail((UUID)holdingHead.get("operationId"))).path("versions");assertThat(mapper.readTree(versions.get(0).path("payloadJson").asText()).path("facts")).isEmpty();
    }
    @Test void approvalRequiresExactSourceContextValuesAndExplicitContraAllowlist() {
        UUID id=movement("WRITE_OFF","InventoryDocument");allocation(id);UUID op=(UUID)capture(id).get("operationId");var command=mapper.createObjectNode().put("documentType","Документ.КоррекцияНоменклатуры").put("context","INVENTORY_CORRECTION").put("organizationId","org");command.putArray("rows").addObject().put("domain","STOCK").put("mmMaterialId",material.toString()).put("mmWarehouseId",warehouse.toString()).put("materialId",UUID.randomUUID().toString()).put("warehouseId",UUID.randomUUID().toString()).put("stockAccountId",UUID.randomUUID().toString()).put("contraAccountId",contra.toString()).put("quantity","-2").put("amount","-20").putArray("contraAnalytics");var approval=mapper.createObjectNode().put("expectedRevision",1);approval.set("nativeCommand",command);
        var tamper=approval.deepCopy();((ObjectNode)tamper.path("nativeCommand").path("rows").get(0)).put("amount","-21");assertThatThrownBy(()->service.approve(op,tamper,"bad")).isInstanceOf(BadRequestException.class);
        assertThat(service.approve(op,approval,"approve-1").get("revision")).isEqualTo(2L);assertThat(service.approve(op,approval,"approve-1").get("replayed")).isEqualTo(true);
        JsonNode lease=mapper.valueToTree(service.poll(request())).path("operations").get(0);assertThat(lease.path("revision").asLong()).isEqualTo(2);var ack=request().put("revision",2).put("leaseToken",lease.path("leaseToken").asText()).put("payloadHash",lease.path("payloadHash").asText()).put("status","APPLIED").put("nativeDocumentId",UUID.randomUUID().toString());service.result(op,ack);assertThatThrownBy(()->service.approve(op,mapper.createObjectNode().put("expectedRevision",2).set("nativeCommand",command),"another")).isInstanceOf(ConflictException.class);
    }
    @Test void committedPostingChannelsCaptureOnceAndHistoricalReconcileDoesNotRecostSources() throws Exception {
        UUID batch=UUID.randomUUID(),resource=UUID.randomUUID();jdbc.update("insert into warehouse_posting_batches(id,tenant_id,company_id,book,operation,context_key,resource_id,idempotency_key,request_hash,posting_date,expected_version,rule_id,rule_version,rule_snapshot,status,receipt_json,committed_at) values(?,?,?,'WAREHOUSE','ISSUE','OWNED',?,'key',?,'2025-04-20',1,?,1,'{}','COMMITTED','{}',current_timestamp)",batch,"out-test",company,resource,"a".repeat(64),UUID.randomUUID());
        for(int i=1;i<=3;i++)jdbc.update("insert into warehouse_posting_effects(batch_id,effect_sequence,effect_type,material_id,warehouse_id,account_code,base_unit_code,quantity,amount,currency_code) values(?,?,?,?,?,'1010',?,?,?,'UZS')",batch,i,i==1?"STOCK":i==2?"ACCOUNT":"COST",material,warehouse,i==3?null:"PCS",i==3?BigDecimal.ZERO:new BigDecimal("-2"),i==1?BigDecimal.ZERO:new BigDecimal("-20"));
        var command=new com.enterprise.mm.warehouse.posting.PostingCommand("WAREHOUSE","ISSUE","OWNED",resource,"key",java.time.LocalDate.of(2025,4,20),1,mapper.createObjectNode().put("source","actual command"));var effects=List.of(new com.enterprise.mm.warehouse.posting.PostingEffect(com.enterprise.mm.warehouse.posting.PostingEffectType.STOCK,material,warehouse,"1010","PCS",new BigDecimal("-2"),BigDecimal.ZERO,null));var receipt=new com.enterprise.mm.warehouse.posting.PostingReceipt(batch,UUID.randomUUID(),1,java.time.LocalDate.of(2025,4,20),effects);
        var captured=tx.execute(s->service.capturePosting(command,receipt));JsonNode detail=mapper.valueToTree(service.detail((UUID)captured.get("operationId")));JsonNode packet=mapper.readTree(detail.path("versions").get(0).path("payloadJson").asText());assertThat(packet.path("facts").size()).isEqualTo(1);assertThat(packet.path("facts").get(0).path("quantity").asText()).isEqualTo("-2");assertThat(packet.path("facts").get(0).path("amount").asText()).isEqualTo("-20");assertThat(packet.path("rawEffects").path("effects").size()).isEqualTo(3);assertThat(packet.path("rawEffects").path("commandContext").path("payload").path("source").asText()).isEqualTo("actual command");
        var scan=mapper.createObjectNode().put("cursor","").put("limit",100);assertThat(service.reconcile(scan).get("captured")).isEqualTo(0);assertThat(service.reconcile(scan).get("complete")).isEqualTo(true);
        assertThat(jdbc.queryForObject("select count(*) from stock_movements",Integer.class)).isZero();assertThat(service.list(10,0)).hasSize(1);
    }
    @Test void transitLossHasNegativeTransitFactsWithoutInventingWarehouseIssue() throws Exception {
        UUID loss=movement("WRITE_OFF","TRANSFER_TRANSIT_LOSS"),transfer=UUID.randomUUID(),allocation=UUID.randomUUID();jdbc.update("update stock_movements set reference_id=? where id=?",transfer,loss);
        jdbc.update("insert into transfer_shipment_allocations(id,tenant_id,company_id,created_at,version,is_delete,name,allocation_sequence,shipment_id,transfer_document_id,transfer_line_id,material_id,unit_code,quantity_scale,source_warehouse_id,dispatched_quantity,original_value,book_value,currency_code,book_currency_code,exchange_rate,consumed_cost_layer_ids) values(?,?,?,current_timestamp,0,false,'Allocation',1,?,?,?,?,'PCS',7,?,2,20,20,'UZS','UZS',1,'[]')",allocation,"out-test",company,UUID.randomUUID(),transfer,UUID.randomUUID(),material,warehouse);
        jdbc.update("insert into transfer_transit_entries(id,tenant_id,company_id,created_at,version,is_delete,name,allocation_id,operation_id,kind,posting_date,quantity_delta,value_delta) values(?,?,?,current_timestamp,0,false,'Loss',?,?,'TRANSIT_LOSS','2025-04-20',-2,-20)",UUID.randomUUID(),"out-test",company,allocation,loss);
        var capture=tx.execute(s->service.captureTransitLoss(loss));JsonNode detail=mapper.valueToTree(service.detail((UUID)capture.get("operationId")));JsonNode packet=mapper.readTree(detail.path("versions").get(0).path("payloadJson").asText());assertThat(packet.path("facts").get(0).path("domain").asText()).isEqualTo("TRANSIT");assertThat(packet.path("facts").get(0).path("amount").asText()).isEqualTo("-20");assertThat(packet.path("contextName").isNull()).isTrue();assertThat(jdbc.queryForObject("select count(*) from stock_movement_allocations",Integer.class)).isZero();
        assertThat(service.reconcile(mapper.createObjectNode().put("cursor","").put("limit",100)).get("captured")).isEqualTo(0);assertThat(service.list(10,0)).hasSize(1);
    }
    @Test void expiredLeaseCannotAcknowledgeAfterAnotherWorkerReceivesFreshFence(){
        UUID id=movement("WRITE_OFF",null);allocation(id);UUID operation=(UUID)capture(id).get("operationId");JsonNode old=mapper.valueToTree(service.poll(request())).path("operations").get(0);jdbc.update("update one_c_warehouse_outbound set lease_until=current_timestamp-interval '1 second' where operation_id=?",operation);
        var ack=request().put("revision",old.path("revision").asLong()).put("leaseToken",old.path("leaseToken").asText()).put("payloadHash",old.path("payloadHash").asText()).put("status","REVIEW_REQUIRED");assertThatThrownBy(()->service.result(operation,ack)).isInstanceOf(ConflictException.class);
        var newRequest=request().put("workerId","second-worker");JsonNode current=mapper.valueToTree(service.poll(newRequest)).path("operations").get(0);assertThat(current.path("leaseToken").asText()).isNotEqualTo(old.path("leaseToken").asText());assertThat(current.path("payloadHash").asText()).isEqualTo(old.path("payloadHash").asText());assertThatThrownBy(()->service.result(operation,ack)).isInstanceOf(ConflictException.class);
        ack.put("workerId","second-worker").put("leaseToken",current.path("leaseToken").asText());assertThat(service.result(operation,ack).get("status")).isEqualTo("REVIEW_REQUIRED");
    }
    @Test void productionAndReturnSourcesCannotUseCorrectionApprovalAndNativeEchoIsExcluded(){
        for(String reference:List.of("PRODUCTION_OPERATION","MATERIAL_RETURN","RETURNABLE_PACKAGING_RETURN","CUSTODY","INSTALLATION_RETURN")){UUID movement=movement("WRITE_OFF",reference);allocation(movement);UUID operation=(UUID)capture(movement).get("operationId");assertThat(service.list(100,0).stream().filter(h->operation.equals(h.get("operationId"))).findFirst().orElseThrow().get("eligibleContext")).isNull();assertThatThrownBy(()->service.approve(operation,mapper.createObjectNode().put("expectedRevision",1),"blocked")).isInstanceOf(ConflictException.class);}
        int previous=service.list(100,0).size();UUID nativeId=movement("RECEIPT","ONE_C_API");assertThat(capture(nativeId).get("skipped")).isEqualTo(true);UUID openingId=movement("RECEIPT","OPENING_STOCK_EXACT");assertThat(capture(openingId).get("skipped")).isEqualTo(true);assertThat(service.list(100,0)).hasSize(previous);
        var foreign=request().put("organizationId","other");assertThatThrownBy(()->service.poll(foreign)).isInstanceOf(BadRequestException.class);assertThatThrownBy(()->service.captureStockMovement(UUID.randomUUID())).isInstanceOf(org.springframework.transaction.IllegalTransactionStateException.class);
    }
    @Test void disabledCaptureDoesNotReadOrAlterSourceAndAppliedStatusCannotHideUnmappedOperation(){
        var disabled=new WarehouseOutboundService(jdbc,mapper,new WarehouseOutboundSettings(false,new WarehouseMirrorSettings(true,"source","org"),""));assertThat(tx.execute(s->disabled.captureStockMovement(UUID.randomUUID())).get("skipped")).isEqualTo(true);assertThat(service.list(10,0)).isEmpty();
        UUID id=movement("WRITE_OFF",null);allocation(id);UUID operation=(UUID)capture(id).get("operationId");JsonNode leased=mapper.valueToTree(service.poll(request())).path("operations").get(0);var ack=request().put("revision",leased.path("revision").asLong()).put("leaseToken",leased.path("leaseToken").asText()).put("payloadHash",leased.path("payloadHash").asText()).put("status","APPLIED").put("nativeDocumentId",UUID.randomUUID().toString());assertThatThrownBy(()->service.result(operation,ack)).isInstanceOf(ConflictException.class);assertThat(service.list(10,0).getFirst().get("state")).isEqualTo("LEASED");
    }
    @Test void oversizedUtf8SourceIsVisibleWithoutLeaseOrInventedProofAndDoesNotBlockNextOperation() throws Exception {
        UUID large=movement("WRITE_OFF",null);allocation(large);UUID blocked=(UUID)capture(large).get("operationId");
        String original=jdbc.queryForObject("select payload_json from one_c_warehouse_outbound_versions where operation_id=?",String.class,blocked);ObjectNode payload=(ObjectNode)mapper.readTree(original);((ObjectNode)payload.path("rawEffects")).put("padding","Я".repeat(4_000_001));String json=payload.toString();assertThat(json.length()).isLessThan(8_000_000);assertThat(json.getBytes(java.nio.charset.StandardCharsets.UTF_8).length).isGreaterThan(8_000_000);String hash=java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(json.getBytes(java.nio.charset.StandardCharsets.UTF_8)));jdbc.update("update one_c_warehouse_outbound_versions set payload_json=?,payload_hash=? where operation_id=?",json,hash,blocked);
        UUID normal=movement("ISSUE",null);allocation(normal);UUID next=(UUID)capture(normal).get("operationId");jdbc.update("update one_c_warehouse_outbound set created_at=current_timestamp-interval '1 minute' where operation_id=?",blocked);
        assertThat(mapper.valueToTree(service.poll(request())).path("operations").size()).isZero();var head=service.list(10,0).stream().filter(h->blocked.equals(h.get("operationId"))).findFirst().orElseThrow();assertThat(head.get("state")).isEqualTo("REVIEW_REQUIRED");assertThat(head.get("pendingReason")).isEqualTo("SOURCE_PAYLOAD_EXCEEDS_NATIVE_LIMIT");assertThat(head.get("leaseUntil")).isNull();assertThat(head.get("attempts")).isEqualTo(0);
        var stored=jdbc.queryForMap("select state,result_json,payload_json,payload_hash from one_c_warehouse_outbound_versions where operation_id=?",blocked);assertThat(stored.get("state")).isEqualTo("REVIEW_REQUIRED");assertThat(stored.get("result_json")).isNull();assertThat(hashPayload(String.valueOf(stored.get("payload_json")))).isEqualTo(hash);assertThat(stored.get("payload_hash")).isEqualTo(hash);
        assertThatThrownBy(()->service.approve(blocked,mapper.createObjectNode().put("expectedRevision",1),"oversized")).isInstanceOf(BadRequestException.class).hasMessageContaining("native limit");assertThat(mapper.valueToTree(service.poll(request())).path("operations").get(0).path("operationId").asText()).isEqualTo(next.toString());
    }
    String hashPayload(String json) throws Exception{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(json.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}
    @Test void approvalCannotGrowAValidSourceBeyondNativeUtf8Limit() throws Exception {
        UUID movement=movement("WRITE_OFF",null);allocation(movement);UUID operation=(UUID)capture(movement).get("operationId");ObjectNode payload=(ObjectNode)mapper.readTree(jdbc.queryForObject("select payload_json from one_c_warehouse_outbound_versions where operation_id=?",String.class,operation));((ObjectNode)payload.path("rawEffects")).put("padding","");int originalBytes=payload.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length;((ObjectNode)payload.path("rawEffects")).put("padding","x".repeat(7_999_900-originalBytes));String json=payload.toString();assertThat(json.getBytes(java.nio.charset.StandardCharsets.UTF_8).length).isEqualTo(7_999_900);String hash=hashPayload(json);jdbc.update("update one_c_warehouse_outbound_versions set payload_json=?,payload_hash=? where operation_id=?",json,hash,operation);
        var command=mapper.createObjectNode().put("documentType","Документ.КоррекцияНоменклатуры").put("context","WRITEOFF").put("organizationId","org");command.putArray("rows").addObject().put("domain","STOCK").put("mmMaterialId",material.toString()).put("mmWarehouseId",warehouse.toString()).put("materialId",UUID.randomUUID().toString()).put("warehouseId",UUID.randomUUID().toString()).put("stockAccountId",UUID.randomUUID().toString()).put("contraAccountId",contra.toString()).put("quantity","-2").put("amount","-20").putArray("contraAnalytics");var approval=mapper.createObjectNode().put("expectedRevision",1);approval.set("nativeCommand",command);
        assertThatThrownBy(()->service.approve(operation,approval,"over-limit")).isInstanceOf(BadRequestException.class).hasMessageContaining("Approved packet exceeds native limit");assertThat(jdbc.queryForObject("select revision from one_c_warehouse_outbound where operation_id=?",Long.class,operation)).isEqualTo(1L);assertThat(jdbc.queryForObject("select count(*) from one_c_warehouse_outbound_versions where operation_id=?",Integer.class,operation)).isEqualTo(1);assertThat(jdbc.queryForObject("select state from one_c_warehouse_outbound where operation_id=?",String.class,operation)).isEqualTo("PENDING");assertThat(hashPayload(jdbc.queryForObject("select payload_json from one_c_warehouse_outbound_versions where operation_id=?",String.class,operation))).isEqualTo(hash);
    }
}
